#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long a, b, c, d, e;
    Point(long long a, long long b, long long c, long long d, long long e) : a(a), b(b), c(c), d(d), e(e) {}
    bool dot(const Point& rhs) const {
        return a * rhs.a + b * rhs.b + c * rhs.c + d * rhs.d + e * rhs.e > 0;
    }
    Point minus(const Point& rhs) const {
        return Point(a - rhs.a, b - rhs.b, c - rhs.c, d - rhs.d, e - rhs.e);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 40) {
        cout << 0 << "\n";
        return 0;
    }
    vector<Point> points;
    for (int i = 0; i < n; i++) {
        long long a, b, c, d, e;
        cin >> a >> b >> c >> d >> e;
        points.emplace_back(a, b, c, d, e);
    }
    if (n < 3) {
        cout << n << "\n";
        for (int i = 1; i <= n; i++) {
            cout << i << "\n";
        }
        return 0;
    }
    vector<int> result;
    for (int center = 0; center < n; center++) {
        bool found = false;
        for (int a = 0; a < n; a++) {
            if (a == center) continue;
            for (int b = 0; b < n; b++) {
                if (b == center || b == a) continue;
                Point A = points[a].minus(points[center]);
                Point B = points[b].minus(points[center]);
                if (A.dot(B)) {
                    found = true;
                    break;
                }
            }
            if (found) break;
        }
        if (!found) result.push_back(center + 1);
    }
    cout << result.size() << "\n";
    for (int id : result) {
        cout << id << "\n";
    }
    return 0;
}

